import { defineConfig } from 'vite';

export default defineConfig({
  server: {
    port: 3000,
  },
  preview: {
    port: 4173,
    host: '0.0.0.0',
    strictPort: true,
  },
});

import { Toast } from '@capacitor/toast';

// Define the custom element <pwa-toast> to ensure it has the correct properties and styling
class PwaToast extends HTMLElement {
  private _text: string = '';
  private _message: string = '';
  private container: HTMLDivElement;

  constructor() {
    super();
    const shadow = this.attachShadow({ mode: 'open' });
    this.container = document.createElement('div');
    this.container.className = 'toast-inner';

    const style = document.createElement('style');
    style.textContent = `
      .toast-inner {
        padding: 12px 24px;
        background-color: #323232;
        color: #ffffff;
        border-radius: 4px;
        font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
        font-size: 14px;
        box-shadow: 0 3px 5px -1px rgba(0,0,0,.2), 0 6px 10px 0 rgba(0,0,0,.14), 0 1px 18px 0 rgba(0,0,0,.12);
        max-width: 80vw;
        word-break: break-word;
        text-align: center;
      }
    `;
    shadow.appendChild(style);
    shadow.appendChild(this.container);
  }

  get text() {
    return this._text;
  }

  set text(val: string) {
    this._text = val;
    this.container.textContent = val;
    this.setAttribute('text', val);
  }

  get message() {
    return this._message;
  }

  set message(val: string) {
    this._message = val;
    this.text = val;
    this.setAttribute('message', val);
  }
}

if (!customElements.get('pwa-toast')) {
  customElements.define('pwa-toast', PwaToast);
}

// Queue options interface
export interface EnqueueToastOptions {
  text: string;
  duration?: number | 'short' | 'long';
  position?: 'top' | 'center' | 'bottom';
}

// Internal Queue Item interface
interface QueueItem {
  text: string;
  duration: number;
  position: 'top' | 'center' | 'bottom';
  resolve: () => void;
  reject: (err: any) => void;
}

// Internal state
const queue: QueueItem[] = [];
let isProcessing = false;
let active = false;
const drainPromises: (() => void)[] = [];

// Helper to resolve drain promises when queue is empty and no toast is active
function resolveDrainPromises() {
  if (queue.length === 0 && !active) {
    while (drainPromises.length > 0) {
      const resolve = drainPromises.shift();
      if (resolve) resolve();
    }
  }
}

// Process the queue sequentially
async function processQueue() {
  if (isProcessing) return;
  isProcessing = true;
  active = true;

  while (queue.length > 0) {
    const item = queue.shift();
    if (!item) continue;

    let toastElement: any = null;

    try {
      // Trigger the Capacitor Toast web plugin show method
      await Toast.show({
        text: item.text,
        duration: item.duration >= 3500 ? 'long' : 'short',
      });

      // Find the newly created pwa-toast element
      toastElement = document.querySelector('pwa-toast');
      if (toastElement) {
        toastElement.setAttribute('data-position', item.position);
        // Force text property if not already synchronized
        if (toastElement.text !== item.text) {
          toastElement.text = item.text;
        }
      }

      // Wait for the duration to elapse
      await new Promise<void>((resolve) => setTimeout(resolve, item.duration));

      // Remove the element from document
      if (toastElement && toastElement.parentNode) {
        toastElement.remove();
      } else {
        const remaining = document.querySelector('pwa-toast');
        if (remaining) {
          remaining.remove();
        }
      }

      item.resolve();
    } catch (err) {
      // Cleanup element on failure
      if (toastElement && toastElement.parentNode) {
        toastElement.remove();
      }
      item.reject(err);
    }
  }

  active = false;
  isProcessing = false;
  resolveDrainPromises();
}

// Public API Implementation
export function enqueueToast(options: EnqueueToastOptions): Promise<void> {
  const text = options.text || '';

  let duration = 2000;
  if (options.duration === 'short') {
    duration = 2000;
  } else if (options.duration === 'long') {
    duration = 3500;
  } else if (typeof options.duration === 'number') {
    duration = options.duration;
  }

  const position = options.position || 'bottom';

  return new Promise<void>((resolve, reject) => {
    queue.push({ text, duration, position, resolve, reject });
    processQueue();
  });
}

export function drainToastQueue(): Promise<void> {
  if (queue.length === 0 && !active) {
    return Promise.resolve();
  }
  return new Promise<void>((resolve) => {
    drainPromises.push(resolve);
  });
}

export function getQueueState(): { pending: number; active: boolean } {
  return {
    pending: queue.length,
    active: active,
  };
}

:root {
  font-family: Inter, system-ui, Avenir, Helvetica, Arial, sans-serif;
  line-height: 1.5;
  font-weight: 400;

  color-scheme: light dark;
  color: rgba(255, 255, 255, 0.87);
  background-color: #242424;

  font-synthesis: none;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  margin: 0;
  display: flex;
  justify-content: center;
  min-width: 320px;
  min-height: 100vh;
  padding: 20px;
}

#app {
  max-width: 600px;
  width: 100%;
  margin: 0 auto;
}

h1 {
  font-size: 2.5rem;
  line-height: 1.1;
  text-align: center;
  margin-bottom: 2rem;
}

h2 {
  font-size: 1.5rem;
  margin-top: 0;
  margin-bottom: 1rem;
  border-bottom: 1px solid #444;
  padding-bottom: 0.5rem;
}

.card {
  background-color: #1a1a1a;
  border-radius: 8px;
  padding: 20px;
  margin-bottom: 20px;
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
}

.form-group {
  margin-bottom: 15px;
  display: flex;
  flex-direction: column;
}

.form-row {
  display: flex;
  gap: 15px;
}

.form-row .form-group {
  flex: 1;
}

label {
  font-size: 0.9rem;
  font-weight: 600;
  margin-bottom: 5px;
  color: #aaa;
}

input, select {
  padding: 10px;
  border-radius: 4px;
  border: 1px solid #444;
  background-color: #333;
  color: #fff;
  font-size: 1rem;
}

input:focus, select:focus {
  outline: none;
  border-color: #646cff;
}

.button-group {
  display: flex;
  gap: 10px;
}

button {
  border-radius: 8px;
  border: 1px solid transparent;
  padding: 0.6em 1.2em;
  font-size: 1em;
  font-weight: 500;
  font-family: inherit;
  background-color: #1a1a1a;
  cursor: pointer;
  transition: border-color 0.25s, background-color 0.25s;
  flex: 1;
}

button:hover {
  border-color: #646cff;
}

button:focus, button:focus-visible {
  outline: 4px auto -webkit-focus-ring-color;
}

button.primary {
  background-color: #646cff;
  color: white;
}

button.primary:hover {
  background-color: #535bf2;
}

button.secondary {
  background-color: #333;
  color: white;
}

button.secondary:hover {
  background-color: #444;
}

.monitor-grid {
  display: flex;
  gap: 20px;
}

.monitor-item {
  flex: 1;
  background-color: #262626;
  padding: 15px;
  border-radius: 6px;
  display: flex;
  flex-direction: column;
  align-items: center;
}

.monitor-item .label {
  font-size: 0.85rem;
  color: #aaa;
  margin-bottom: 5px;
}

.monitor-item .value {
  font-size: 1.5rem;
  font-weight: bold;
}

.badge-active {
  color: #4caf50;
}

.badge-inactive {
  color: #f44336;
}

.status-text {
  margin-top: 10px;
  font-style: italic;
  color: #888;
  text-align: center;
}

.log-console {
  background-color: #000;
  color: #0f0;
  font-family: monospace;
  padding: 10px;
  border-radius: 4px;
  height: 150px;
  overflow-y: auto;
  font-size: 0.85rem;
}

.log-line {
  margin-bottom: 4px;
}

/* Position pwa-toast */
pwa-toast {
  position: fixed;
  left: 50%;
  transform: translateX(-50%);
  z-index: 10000;
  pointer-events: none;
}

pwa-toast[data-position="top"] {
  top: 40px;
}

pwa-toast[data-position="center"] {
  top: 50%;
  transform: translate(-50%, -50%);
}

pwa-toast[data-position="bottom"] {
  bottom: 40px;
}

import { enqueueToast, drainToastQueue, getQueueState } from './toastQueue';

// Attach to window for external/automated access
(window as any).enqueueToast = enqueueToast;
(window as any).drainToastQueue = drainToastQueue;
(window as any).getQueueState = getQueueState;

// UI elements
const toastTextInput = document.getElementById('toast-text') as HTMLInputElement;
const toastDurationSelect = document.getElementById('toast-duration') as HTMLSelectElement;
const toastPositionSelect = document.getElementById('toast-position') as HTMLSelectElement;

const btnEnqueue = document.getElementById('btn-enqueue') as HTMLButtonElement;
const btnEnqueueBurst = document.getElementById('btn-enqueue-burst') as HTMLButtonElement;
const btnDrain = document.getElementById('btn-drain') as HTMLButtonElement;

const statePending = document.getElementById('state-pending') as HTMLSpanElement;
const stateActive = document.getElementById('state-active') as HTMLSpanElement;
const drainStatus = document.getElementById('drain-status') as HTMLDivElement;
const logConsole = document.getElementById('log-console') as HTMLDivElement;

// Logging helper
function log(message: string) {
  const line = document.createElement('div');
  line.className = 'log-line';
  line.textContent = `[${new Date().toLocaleTimeString()}] ${message}`;
  logConsole.appendChild(line);
  logConsole.scrollTop = logConsole.scrollHeight;
}

// Update the state display in real-time
function updateStateDisplay() {
  const state = getQueueState();
  statePending.textContent = state.pending.toString();

  if (state.active) {
    stateActive.textContent = 'Active';
    stateActive.className = 'value badge-active';
  } else {
    stateActive.textContent = 'Inactive';
    stateActive.className = 'value badge-inactive';
  }
}

// Set up periodic/event-driven state updates
setInterval(updateStateDisplay, 100);

// Enqueue single toast
btnEnqueue.addEventListener('click', async () => {
  const text = toastTextInput.value;
  const durationVal = toastDurationSelect.value;
  const position = toastPositionSelect.value as 'top' | 'center' | 'bottom';

  let duration: number | 'short' | 'long' = 2000;
  if (durationVal === 'short' || durationVal === 'long') {
    duration = durationVal;
  } else {
    duration = parseInt(durationVal, 10);
  }

  log(`Enqueuing: "${text}" (duration: ${duration}, position: ${position})`);
  updateStateDisplay();

  try {
    await enqueueToast({ text, duration, position });
    log(`Finished: "${text}"`);
  } catch (err) {
    log(`Error: "${text}" failed: ${err}`);
  }
  updateStateDisplay();
});

// Enqueue burst
btnEnqueueBurst.addEventListener('click', () => {
  log('Starting burst of 5 toasts...');
  const durationVal = toastDurationSelect.value;
  const position = toastPositionSelect.value as 'top' | 'center' | 'bottom';

  let duration: number | 'short' | 'long' = 2000;
  if (durationVal === 'short' || durationVal === 'long') {
    duration = durationVal;
  } else {
    duration = parseInt(durationVal, 10);
  }

  for (let i = 1; i <= 5; i++) {
    const text = `Burst Toast #${i}`;
    log(`Enqueuing synchronously: "${text}"`);
    enqueueToast({ text, duration, position })
      .then(() => log(`Finished: "${text}"`))
      .catch((err) => log(`Error: "${text}" failed: ${err}`));
  }
  updateStateDisplay();
});

// Drain queue
btnDrain.addEventListener('click', async () => {
  log('Awaiting queue drain...');
  drainStatus.textContent = 'Draining...';
  updateStateDisplay();

  const startTime = Date.now();
  await drainToastQueue();

  const elapsed = Date.now() - startTime;
  drainStatus.textContent = `Drained in ${elapsed}ms!`;
  log('Queue completely drained.');
  updateStateDisplay();
});

log('Toast Queue Manager Initialized.');
updateStateDisplay();
